package com.soulbrowser.app
object TabDragReorderHelper { fun moveTab(tabs:List<SoulTab>,fromId:String,toId:String):List<SoulTab>{val a=tabs.indexOfFirst{it.id==fromId};val b=tabs.indexOfFirst{it.id==toId};if(a<0||b<0||a==b)return tabs;return tabs.toMutableList().apply{add(b,removeAt(a))}};fun moveTabToWorkspace(tabs:List<SoulTab>,tabId:String,targetWorkspaceId:String)=tabs.map{if(it.id==tabId)it.copy(workspaceId=targetWorkspaceId)else it};fun closeOtherTabsInWorkspace(tabs:List<SoulTab>,workspaceId:String,keepTabId:String)=tabs.filter{!(it.workspaceId==workspaceId&&it.id!=keepTabId&&!it.isPinned)} }